import sys

def main():
    s = sys.stdin.read().split()[0]
    last = {}
    left = best = best_start = 0
    for right, ch in enumerate(s):
        j = last.get(ch, -1)
        if j >= left:
            left = j + 1
        last[ch] = right
        if right - left + 1 > best:
            best = right - left + 1
            best_start = left
    print(best)
    print(s[best_start:best_start + best])

